def extract_json(text):
    best = None
    for span in balanced_brace_spans(text):
        try:
            obj = json.loads(span)
        except json.JSONDecodeError:
            continue
        if isinstance(obj, dict) and ('verdict' in obj or 'blocking_findings' in obj):
            best = obj   # keep the LAST one that parses
    return best
